// src/modules/chat/ws/events/mark-read/handler.ts
init_logger();
var markReadHandler = async (ctx, socket, input) => {
  const { conversationId, watermarkId } = input;
  const { userId } = socket.data;
  try {
    const member = await ctx.db.chatMember.findFirst({
      where: { conversationId, userId }
    });
    if (!member) {
      logger.warn({ msg: "Member not found", userId, conversationId });
      return;
    }
    const message = await ctx.db.chatMessage.findUnique({
      where: { id: watermarkId },
      select: {
        id: true,
        sequence: true,
        conversationId: true,
        authorUserId: true
      }
    });
    if (!message || message.conversationId !== conversationId) {
      logger.warn({ msg: "Message not found", watermarkId, conversationId });
      return;
    }
    await updateReadWatermark(conversationId, userId, watermarkId, message.sequence);
    const conversation = await ctx.db.chatConversation.findUnique({
      where: { id: conversationId },
      select: { type: true }
    });
    if (conversation?.type === "DM") {
      const otherMember = await ctx.db.chatMember.findFirst({
        where: {
          conversationId,
          userId: { not: userId }
        },
        select: { userId: true }
      });
      if (otherMember) {
        await publishReadReceipt(ctx, conversationId, userId, watermarkId, message.sequence, [otherMember.userId]);
      }
    } else if (conversation?.type === "GROUP_DM") {
      if (message.authorUserId !== userId) {
        await publishReadReceipt(ctx, conversationId, userId, watermarkId, message.sequence, [message.authorUserId]);
      }
    }
    await readReceiptQueue.add("batch-update", {
      conversationId,
      userId,
      watermarkId,
      sequence: message.sequence
    }, {
      delay: 5000,
      jobId: `${conversationId}:${userId}`
    });
    socket.send(JSON.stringify({
      type: "ack",
      nonce: input.nonce,
      success: true
    }));
  } catch (error48) {
    logger.error({
      msg: "mark-read error",
      error: error48,
      conversationId,
      userId
    });
  }
};
async function publishReadReceipt(ctx, conversationId, readerId, watermarkId, sequence, targetUserIds) {
  const event = {
    type: "chat:message-read" /* MessageRead */,
    data: {
      conversationId,
      userId: readerId,
      watermarkId,
      watermarkSequence: sequence,
      timestamp: Date.now()
    }
  };
  for (const targetUserId of targetUserIds) {
    const topic = `user:${targetUserId}:events`;
    await ctx.redis.publish(topic, JSON.stringify(event));
  }
}

