import fs2 from "fs";
import path3 from "path";
var __dirname = "/home/jimmy/Desktop/DEV/official-collabify/server/src/modules/chat/domain/reactions/scripts";
var addReactionScript = fs2.readFileSync(path3.join(__dirname, "add-reaction.lua"), "utf-8");
var removeReactionScript = fs2.readFileSync(path3.join(__dirname, "remove-reaction.lua"), "utf-8");

// src/modules/chat/domain/reactions/redis-helpers.ts
init_logger();
var addReaction = async (redis2, params) => {
  const { messageId, userId, emoji: emoji3, conversationId } = params;
  const timestamp = Date.now();
  const result = await redis2.eval(addReactionScript, 4, `reactions:${messageId}:${emoji3}`, `reaction-counts:${messageId}`, `user-reactions:${userId}`, `reaction-events:${conversationId}`, timestamp, userId, emoji3, messageId, conversationId);
  return { added: result === 1 };
};
var removeReaction = async (redis2, params) => {
  const { messageId, userId, emoji: emoji3, conversationId } = params;
  const timestamp = Date.now();
  const result = await redis2.eval(removeReactionScript, 4, `reactions:${messageId}:${emoji3}`, `reaction-counts:${messageId}`, `user-reactions:${userId}`, `reaction-events:${conversationId}`, userId, emoji3, messageId, conversationId, timestamp);
  return { removed: result === 1 };
};
var getReactionCounts = async (redis2, messageId) => {
  const counts = await redis2.hgetall(`reaction-counts:${messageId}`);
  return Object.fromEntries(Object.entries(counts).map(([emoji3, count]) => [emoji3, parseInt(count, 10)]));
};
var getReactionUsers = async (redis2, messageId, emoji3, cursor = 0, limit = 20) => {
  const userIds = await redis2.zrange(`reactions:${messageId}:${emoji3}`, cursor, cursor + limit - 1, "REV");
  return {
    userIds,
    nextCursor: userIds.length === limit ? cursor + limit : null
  };
};
var hasUserReacted = async (redis2, messageId, userId, emoji3) => {
  const isMember = await redis2.sismember(`user-reactions:${userId}`, `${messageId}:${emoji3}`);
  return isMember === 1;
};
var syncReactionEvents = async (redis2, conversationId, lastEventId = "0-0") => {
  const streamKey = `reaction-events:${conversationId}`;
  const events = await redis2.xread("STREAMS", streamKey, lastEventId);
  if (!events || events.length === 0) {
    return [];
  }
  const streamData = events[0][1];
  return streamData.map((event) => {
    const eventId = event[0];
    const fields = event[1];
    const fieldMap = {};
    for (let i = 0;i < fields.length; i += 2) {
      fieldMap[fields[i]] = fields[i + 1];
    }
    return {
      eventId,
      action: fieldMap.action,
      messageId: fieldMap.messageId,
      userId: fieldMap.userId,
      emoji: fieldMap.emoji,
      timestamp: parseInt(fieldMap.ts, 10)
    };
  });
};
var rebuildReactionCache = async (redis2, messageId, reactions) => {
  if (reactions.length === 0)
    return;
  const pipeline = redis2.pipeline();
  const emojiCounts = new Map;
  for (const r of reactions) {
    pipeline.zadd(`reactions:${messageId}:${r.emoji}`, r.createdAt.getTime(), r.userId);
    emojiCounts.set(r.emoji, (emojiCounts.get(r.emoji) || 0) + 1);
    pipeline.sadd(`user-reactions:${r.userId}`, `${messageId}:${r.emoji}`);
  }
  for (const [emoji3, count] of emojiCounts) {
    pipeline.hset(`reaction-counts:${messageId}`, emoji3, count);
  }
  const ttl = 604800;
  for (const emoji3 of emojiCounts.keys()) {
    pipeline.expire(`reactions:${messageId}:${emoji3}`, ttl);
  }
  pipeline.expire(`reaction-counts:${messageId}`, ttl);
  await pipeline.exec();
  logger.info({ messageId, count: reactions.length }, "Rebuilt reaction cache");
};

// src/modules/chat/ws/events/add-reaction/handler.ts
var addReactionHandler = async (ctx, socket, input) => {
  const { messageId, emoji: emoji3, tempId } = input;
  const { userId } = socket.data;
  try {
    const message = await ctx.db.chatMessage.findUnique({
      where: { id: messageId },
      select: { id: true, conversationId: true }
    });
    if (!message) {
      socket.send(createErrorFrame(tempId || messageId, "chat:add-reaction", "MESSAGE_NOT_FOUND", "Message not found"));
      return;
    }
    const membership = await ctx.db.chatMember.findUnique({
      where: {
        conversationId_userId: {
          conversationId: message.conversationId,
          userId
        }
      }
    });
    if (!membership) {
      socket.send(createErrorFrame(tempId || messageId, "chat:add-reaction", "FORBIDDEN", "Not a conversation member"));
      return;
    }
    const { added } = await addReaction(ctx.redis, {
      messageId,
      userId,
      emoji: emoji3,
      conversationId: message.conversationId
    });
    socket.send(createSuccessFrame(tempId, "chat:reaction-ack", {
      messageId,
      emoji: emoji3,
      status: added ? "added" : "duplicate"
    }));
    if (added) {
      const topic = KeyFactory.ConversationTopic(message.conversationId);
      try {
        await ctx.redis.publish(topic, JSON.stringify({
          type: "chat:reaction-added" /* ReactionAdded */,
          data: {
            messageId,
            userId,
            emoji: emoji3,
            timestamp: Date.now()
          }
        }));
      } catch (pubsubError) {
        logger.error({ error: pubsubError, messageId, userId, emoji: emoji3 }, "Failed to publish reaction-added event via Pub/Sub");
      }
      logger.info({ messageId, userId, emoji: emoji3 }, "Reaction added");
    }
  } catch (error48) {
    logger.error({ error: error48, messageId, userId, emoji: emoji3 }, "Failed to add reaction");
    socket.send(createErrorFrame(tempId || messageId, "chat:add-reaction", "INTERNAL_ERROR", "Failed to add reaction"));
  }
};

