var QuotaService = {
  async enforceQuota(userId, resourceKey) {
    const allowed = await this.checkQuota(userId, resourceKey);
    if (!allowed) {
      throw AppError.forbidden(`Quota exceeded for ${resourceKey}. Please upgrade your plan.`);
    }
  },
  async checkQuota(userId, resourceKey) {
    const subscription2 = await db.subscription.findUnique({
      where: { userId },
      include: {
        plan: {
          include: { limits: true }
        },
        overrides: true
      }
    });
    let limit = -1;
    if (!subscription2) {
      if (resourceKey === "MAX_OWNED_WORKSPACES")
        return await this.checkHardcoded(userId, WORKSPACE_LIMITS.MAX_OWNED_WORKSPACES);
      return true;
    }
    const override = subscription2.overrides.find((o) => o.resourceKey === resourceKey);
    const planLimit = subscription2.plan.limits.find((l) => l.resourceKey === resourceKey);
    if (override) {
      limit = override.limitValue;
    } else if (planLimit) {
      limit = planLimit.limitValue;
    }
    if (limit === -1)
      return true;
    const usage = await this.calculateUsage(userId, resourceKey);
    return usage < limit;
  },
  async calculateUsage(userId, resourceKey) {
    if (resourceKey === "MAX_OWNED_WORKSPACES") {
      return db.workspace.count({
        where: {
          members: { some: { userId, role: "OWNER" } },
          deletedAt: null
        }
      });
    }
    return 0;
  },
  async checkHardcoded(userId, max) {
    const usage = await this.calculateUsage(userId, "MAX_OWNED_WORKSPACES");
    return usage < max;
  }
};

