var createOnboardingWorkspace = async (input, ctx) => {
  const { userId, userFullName, slug } = input;
  const { redis: redis2 } = ctx;
  const keys2 = createLockKeys("workspace");
  const userLockKey = keys2.resource(`onboarding:${userId}`);
  const acquired = await LockingService.acquire(userLockKey, "1", 10);
  if (!acquired) {
    throw AppError.conflict("Onboarding is already in progress. Please wait.", "IDEMPOTENCY_LOCKED");
  }
  try {
    const existing = await getMyWorkspaces({ userId }, ctx);
    if (existing.length > 0) {
      logger.info({ userId, workspaceId: existing[0].id }, "Onboarding Idempotency: Workspace already exists");
      return existing[0];
    }
    const MAX_RETRIES = 5;
    let attempts = 0;
    const baseSlug = slug || SlugUtil.sanitize(userFullName) || "workspace";
    let finalSlug = null;
    while (attempts < MAX_RETRIES) {
      const candidateSlug = slug && attempts === 0 ? slug : SlugUtil.generateNext(baseSlug, attempts);
      const check2 = await checkSlugAvailability({
        slug: candidateSlug,
        userId
      }, ctx);
      if (check2.available) {
        finalSlug = candidateSlug;
        break;
      }
      if (slug && attempts === 0) {
        throw AppError.conflict(`The slug '${slug}' is unavailable. Please choose another.`, "WORKSPACE_ONBOARDING_CUSTOM_SLUG_TAKEN");
      }
      attempts++;
    }
    if (!finalSlug) {
      throw new AppError("Could not generate a unique workspace URL. Please try again.", "WORKSPACE_ONBOARDING_SLUG_GENERATION_FAILED");
    }
    return await createWorkspace({
      userId,
      name: userFullName + "'s Workspace",
      slug: finalSlug
    }, ctx);
  } finally {
    await LockingService.release(userLockKey, "1");
  }
};
