var getNotifications = async (input, ctx) => {
  const { db: db2 } = ctx;
  const { userId, limit, cursor, filter } = input;
  if (!userId) {
    throw AppError.unauthorized("Unauthorized");
  }
  const where = {
    recipientUserId: userId,
    ...filter?.isRead !== undefined ? { isRead: filter.isRead } : {}
  };
  const notifications = await db2.notification.findMany({
    where,
    take: limit + 1,
    cursor: cursor ? { id: cursor } : undefined,
    orderBy: { createdAt: "desc" }
  });
  let hasNextPage = false;
  if (notifications.length > limit) {
    hasNextPage = true;
    notifications.pop();
  }
  const nextCursor = hasNextPage ? notifications[notifications.length - 1].id : null;
  return {
    items: notifications,
    pageInfo: {
      hasNextPage,
      endCursor: nextCursor
    }
  };
};
