// src/modules/chat/jobs/persist-reactions.ts
init_db();
init_logger();
var persistReactionsHandler = async (job2) => {
  const { reactions } = job2.data;
  const toAdd = reactions.filter((r) => r.action === "add");
  const toRemove = reactions.filter((r) => r.action === "remove");
  if (toAdd.length > 0) {
    const messageIds = [...new Set(toAdd.map((r) => r.messageId))];
    const existingMessages = await db.chatMessage.findMany({
      where: {
        id: { in: messageIds },
        deletedAt: null
      },
      select: { id: true }
    });
    const validMessageIds = new Set(existingMessages.map((m) => m.id));
    const reactionsWithValidMessages = toAdd.filter((r) => validMessageIds.has(r.messageId));
    if (reactionsWithValidMessages.length === 0) {
      logger.info("No valid messages found for reactions");
      return;
    }
    const userIds = [
      ...new Set(reactionsWithValidMessages.map((r) => r.userId))
    ];
    const existingUsers = await db.user.findMany({
      where: {
        id: { in: userIds },
        deletedAt: null
      },
      select: { id: true }
    });
    const validUserIds = new Set(existingUsers.map((u) => u.id));
    const fullyValidReactions = reactionsWithValidMessages.filter((r) => validUserIds.has(r.userId));
    if (fullyValidReactions.length === 0) {
      logger.info("No valid users found for reactions");
      return;
    }
    await db.messageReaction.createMany({
      data: fullyValidReactions.map((r) => ({
        messageId: r.messageId,
        userId: r.userId,
        emoji: r.emoji,
        createdAt: new Date(r.timestamp)
      })),
      skipDuplicates: true
    });
    const skipped = toAdd.length - fullyValidReactions.length;
    if (skipped > 0) {
      logger.warn({ skipped, total: toAdd.length }, "Skipped reactions for non-existent messages or users");
    }
  }
  if (toRemove.length > 0) {
    await db.messageReaction.deleteMany({
      where: {
        OR: toRemove.map((r) => ({
          messageId: r.messageId,
          userId: r.userId,
          emoji: r.emoji
        }))
      }
    });
  }
  logger.info({ added: toAdd.length, removed: toRemove.length }, "Reactions batch persisted");
};

// src/modules/chat/jobs/reconcile-reactions.ts
init_db();
init_redis();
init_logger();
var reconcileReactionsHandler = async (job2) => {
  const { messageIds, forceRebuild = false } = job2.data;
  let targetMessageIds = messageIds;
  if (!targetMessageIds || targetMessageIds.length === 0) {
    const sevenDaysAgo = new Date(Date.now() - 7 * 24 * 60 * 60 * 1000);
    const recentMessages = await db.chatMessage.findMany({
      where: {
        createdAt: { gte: sevenDaysAgo },
        reactions: {
          some: {}
        }
      },
      select: { id: true },
      take: 1000
    });
    targetMessageIds = recentMessages.map((m) => m.id);
  }
  logger.info({ count: targetMessageIds.length, forceRebuild }, "Starting reaction reconciliation");
  const deletedMessages = await db.chatMessage.findMany({
    where: {
      deletedAt: { not: null },
      reactions: {
        some: {}
      }
    },
    select: { id: true }
  });
  if (deletedMessages.length > 0) {
    logger.info({ count: deletedMessages.length }, "Cleaning up reactions for deleted messages");
    for (const msg of deletedMessages) {
      await db.messageReaction.deleteMany({
        where: { messageId: msg.id }
      });
      const redisCounts = await getReactionCounts(appRedis, msg.id);
      const pipeline = appRedis.pipeline();
      for (const emoji3 of Object.keys(redisCounts)) {
        pipeline.del(`reactions:${msg.id}:${emoji3}`);
      }
      pipeline.del(`reaction-counts:${msg.id}`);
      await pipeline.exec();
    }
  }
  let desyncCount = 0;
  let rebuiltCount = 0;
  for (const messageId of targetMessageIds) {
    try {
      const dbReactions = await db.messageReaction.findMany({
        where: { messageId },
        select: { emoji: true, userId: true, createdAt: true }
      });
      const redisCounts = await getReactionCounts(appRedis, messageId);
      const dbChecksum = computeReactionChecksum(dbReactions);
      const redisChecksum = computeCountsChecksum(redisCounts);
      if (forceRebuild || dbChecksum !== redisChecksum) {
        desyncCount++;
        logger.warn({
          messageId,
          dbChecksum,
          redisChecksum,
          dbCount: dbReactions.length,
          redisTotal: Object.values(redisCounts).reduce((a, b) => a + b, 0)
        }, "Desync detected, rebuilding cache");
        const pipeline = appRedis.pipeline();
        const allEmojis = new Set([
          ...dbReactions.map((r) => r.emoji),
          ...Object.keys(redisCounts)
        ]);
        for (const emoji3 of allEmojis) {
          pipeline.del(`reactions:${messageId}:${emoji3}`);
        }
        pipeline.del(`reaction-counts:${messageId}`);
        await pipeline.exec();
        if (dbReactions.length > 0) {
          await rebuildReactionCache(appRedis, messageId, dbReactions);
          rebuiltCount++;
        }
      }
    } catch (error48) {
      logger.error({ error: error48, messageId }, "Failed to reconcile reactions for message");
    }
    if (targetMessageIds.length > 100) {
      await new Promise((r) => setTimeout(r, 10));
    }
  }
  logger.info({
    total: targetMessageIds.length,
    desyncCount,
    rebuiltCount
  }, "Reaction reconciliation complete");
  return { desyncCount, rebuiltCount };
};
function computeReactionChecksum(reactions) {
  if (reactions.length === 0)
    return "empty";
  const sorted = reactions.map((r) => `${r.emoji}:${r.userId}:${r.createdAt.getTime()}`).sort();
  return sorted.join("|").length.toString() + "-" + sorted.length;
}
function computeCountsChecksum(counts) {
  if (Object.keys(counts).length === 0)
    return "empty";
  const sorted = Object.entries(counts).sort(([a], [b]) => a.localeCompare(b)).map(([emoji3, count]) => `${emoji3}:${count}`).join("|");
  return sorted.length.toString() + "-" + Object.values(counts).reduce((a, b) => a + b, 0);
}

