        const result = await bpubRedis.xreadgroup("GROUP", WORKER_GROUP_NAME, CONSUMER_NAME, "COUNT", BATCH_COUNT, "BLOCK", BLOCK_MS, "STREAMS", ...fullStreamKeys, ...ids);
