init_redis();
init_logger();
import crypto2, { createHash as createHash3 } from "crypto";
var COORDINATOR_ID = crypto2.randomUUID();
var CONVERSATION_TTL_MS = 24 * 60 * 60 * 1000;
var workerCoordinator = {
  isRunning: false,
  intervalId: null,
  lastWorkerIds: [],
  lastConversationEpoch: 0,
  async init() {
    this.isRunning = true;
    logger.info({ coordinatorId: COORDINATOR_ID }, "Starting Worker Coordinator (Hardened)");
    this.startLoop();
  },
  startLoop() {
    this.intervalId = setInterval(() => this.tick(), 1000);
  },
  async tick() {
    try {
      const isLeader = await this.ensureLeadership();
      if (!isLeader)
        return;
      const now = Date.now();
      await appRedis.zremrangebyscore(KeyFactory.ActiveConversations, "-inf", now - CONVERSATION_TTL_MS);
      await appRedis.zremrangebyscore(KeyFactory.WorkerRegistry, "-inf", now - 30000);
      const workers = await appRedis.zrangebyscore(KeyFactory.WorkerRegistry, now - 1e4, "+inf");
      const sortedWorkers = workers.sort();
      const workersChanged = JSON.stringify(sortedWorkers) !== JSON.stringify(this.lastWorkerIds);
      const currentConversationEpochStr = await appRedis.get(KeyFactory.EpochConversations);
      const currentConversationEpoch = parseInt(currentConversationEpochStr || "0", 10);
      const conversationsChanged = currentConversationEpoch > this.lastConversationEpoch;
      if (!workersChanged && !conversationsChanged) {
        return;
      }
      logger.info({ workersChanged, conversationsChanged, currentConversationEpoch }, "Coordinator: Rebalance Triggered");
      await this.performRebalance(sortedWorkers);
      this.lastWorkerIds = sortedWorkers;
      this.lastConversationEpoch = currentConversationEpoch;
    } catch (err) {
      logger.error({ err }, "Coordinator: Tick Failed");
    }
  },
  async ensureLeadership() {
    const lockKey = KeyFactory.CoordinatorLock;
    const acquired = await appRedis.set(lockKey, COORDINATOR_ID, "PX", 3000, "NX");
    if (acquired === "OK")
      return true;
    const luaScript = `
      if redis.call("get", KEYS[1]) == ARGV[1] then
        return redis.call("pexpire", KEYS[1], ARGV[2])
      else
        return 0
      end
    `;
    const renewed = await appRedis.eval(luaScript, 1, lockKey, COORDINATOR_ID, 3000);
    return renewed === 1;
  },
  async performRebalance(workers) {
    const activeConversations = await appRedis.zrange(KeyFactory.ActiveConversations, 0, -1);
    if (activeConversations.length === 0 || workers.length === 0)
      return;
    const assignments = {};
    workers.forEach((w) => assignments[w] = []);
    for (const conversationId of activeConversations) {
      const assignedWorker = this.rendezvousHash(conversationId, workers);
      if (assignedWorker) {
        assignments[assignedWorker].push(conversationId);
      }
    }
    for (const [workerId, channels] of Object.entries(assignments)) {
      const assignmentKey = KeyFactory.WorkerAssignment(workerId);
      const hashKey = KeyFactory.AssignmentHash(workerId);
      channels.sort();
      const newHash = createHash3("md5").update(JSON.stringify(channels)).digest("hex");
      const lastHash = await appRedis.get(hashKey);
      if (lastHash === newHash) {
        continue;
      }
      if (channels.length > 0) {
        await appRedis.multi().del(assignmentKey).sadd(assignmentKey, ...channels).set(hashKey, newHash).exec();
      } else {
        await appRedis.multi().del(assignmentKey).del(hashKey).exec();
      }
    }
  },
  rendezvousHash(item, nodes) {
    if (nodes.length === 0)
      return null;
    let maxWeight = -1;
    let selectedNode = null;
    for (const node of nodes) {
      const hash2 = createHash3("md5").update(`${item}:${node}`).digest("hex");
      const weight = parseInt(hash2.substring(0, 12), 16);
      if (weight > maxWeight) {
        maxWeight = weight;
        selectedNode = node;
      }
    }
    return selectedNode;
  },
  stop() {
    this.isRunning = false;
    if (this.intervalId)
      clearInterval(this.intervalId);
  }
};

