// src/modules/chat/services/check-channel-availability/handler.ts
init_errors3();
var handler31 = async (input, ctx) => {
  const { userId } = ctx.auth;
  if (!userId)
    throw AppError.unauthorized("User not authenticated");
  const { projectId, slug } = input;
  const { db: db2, redis: redis2 } = ctx;
  const normalizedSlug = SlugUtil.sanitize(slug).toLowerCase();
  const keys2 = createLockKeys("channel", { type: "project", id: projectId });
  const allowed = await checkRateLimit(keys2.rateLimit(userId), 20, 60);
  if (!allowed) {
    return {
      available: false,
      message: "Too many attempts. Please wait.",
      reason: "RATE_LIMIT_EXCEEDED"
    };
  }
  const existingDB = await db2.chatConversation.findFirst({
    where: {
      projectId,
      type: "CHANNEL",
      name: { equals: normalizedSlug, mode: "insensitive" }
    }
  });
  if (existingDB) {
    return {
      available: false,
      message: "Channel already exists",
      reason: "CHANNEL_NAME_TAKEN_PERMANENT"
    };
  }
  const userResKey = keys2.userReservation(userId);
  const previousSlug = await redis2.get(userResKey);
  const lockKey = keys2.resource(normalizedSlug);
  const ttl = 180;
  const oldLockKey = previousSlug ? keys2.resource(previousSlug) : `dummy:lock:${userId}`;
  try {
    const reserved = await LockingService.switch(oldLockKey, lockKey, userId, ttl, userResKey, normalizedSlug);
    if (!reserved) {
      return {
        available: false,
        message: "Channel name is currently reserved by another user",
        reason: "CHANNEL_NAME_RESERVATION_FAILED"
      };
    }
    return {
      available: true,
      reservationId: lockKey,
      message: "Channel name reserved for 3 minutes"
    };
  } catch (error48) {
    throw new AppError("Internal Redis Error", "INTERNAL_SERVER_ERROR", 500);
  }
};
