// src/modules/chat/queries/get-messages-delta/handler.ts
var handler65 = async (input, ctx) => {
  const { conversationId, afterSequence, limit } = input;
  const messages = await ctx.db.chatMessage.findMany({
    where: {
      conversationId,
      ...afterSequence !== undefined ? { sequence: { gt: afterSequence } } : { sequence: { gt: 0 } }
    },
    orderBy: {
      sequence: "asc"
    },
    take: limit + 1,
    select: {
      id: true,
      conversationId: true,
      authorUserId: true,
      content: true,
      type: true,
      sequence: true,
      streamId: true,
      createdAt: true,
      deletedAt: true,
      metadata: true,
      parentMessageId: true
    }
  });
  const hasMore = messages.length > limit;
  if (hasMore) {
    messages.pop();
  }
  const lastMsg = messages[messages.length - 1];
  const lastSequence = lastMsg?.sequence || afterSequence || 0;
  return {
    messages,
    hasMore,
    lastSequence
  };
};
