// src/modules/chat/queries/get-history/handler.ts
async function handler67(input, ctx) {
  const { conversationId, beforeSequence, limit } = GetHistoryInputSchema.parse(input);
  const fetchLimit = limit ?? 50;
  const messages = await ctx.db.chatMessage.findMany({
    where: {
      conversationId,
      sequence: {
        lt: beforeSequence
      },
      deletedAt: null
    },
    orderBy: {
      sequence: "desc"
    },
    take: fetchLimit + 1,
    include: {}
  });
  const hasMore = messages.length > fetchLimit;
  const slicedMessages = hasMore ? messages.slice(0, fetchLimit) : messages;
  const minSequence = slicedMessages.length > 0 ? slicedMessages[slicedMessages.length - 1].sequence : null;
  return {
    messages: slicedMessages,
    hasMore,
    minSequence
  };
}
