// src/modules/chat/queries/get-unread-counts/handler.ts
var handler71 = async (input, ctx) => {
  const { workspaceId, projectId } = input;
  const userId = ctx.auth.userId;
  const members = await ctx.db.chatMember.findMany({
    where: {
      userId,
      conversation: {
        workspaceId,
        projectId,
        deletedAt: null
      }
    },
    select: {
      conversationId: true,
      lastReadSeq: true,
      conversation: {
        select: {
          lastSequence: true
        }
      }
    }
  });
  const pipeline = ctx.redis.pipeline();
  members.forEach((member) => {
    pipeline.zscore(`read:${member.conversationId}`, userId);
  });
  const results = await pipeline.exec();
  const conversations = members.map((member, index) => {
    const userReadSeq = results?.[index]?.[1] ? parseInt(results[index][1]) : member.lastReadSeq || 0;
    const lastMsgSeq = member.conversation.lastSequence || 0;
    const unreadCount = Math.max(0, lastMsgSeq - userReadSeq);
    return {
      conversationId: member.conversationId,
      unreadCount,
      lastUnreadMessageId: null
    };
  });
  return { conversations };
};
