var handler72 = async (input, ctx) => {
  const { messageId } = input;
  const message = await ctx.db.chatMessage.findUnique({
    where: { id: messageId },
    select: {
      conversationId: true,
      sequence: true
    }
  });
  if (!message) {
    throw new Error("MESSAGE_NOT_FOUND");
  }
  const readCount = await getMessageReadCount(messageId);
  const readerIds = await getUsersWhoRead(message.conversationId, message.sequence);
  if (readerIds.length > 0) {
    const users = await ctx.db.user.findMany({
      where: { id: { in: readerIds } },
      select: {
        id: true,
        fullName: true,
        avatarUrl: true
      }
    });
    const totalMembers2 = await ctx.db.chatMember.count({
      where: { conversationId: message.conversationId }
    });
    return {
      readBy: users.map((u) => ({
        userId: u.id,
        username: u.fullName || "Unknown",
        avatarUrl: u.avatarUrl
      })),
      totalReads: readCount || readerIds.length,
      totalMembers: totalMembers2
    };
  }
  const readers = await ctx.db.chatMember.findMany({
    where: {
      conversationId: message.conversationId,
      lastReadSeq: { gte: message.sequence }
    },
    select: {
      user: {
        select: {
          id: true,
          fullName: true,
          avatarUrl: true
        }
      }
    }
  });
  const totalMembers = await ctx.db.chatMember.count({
    where: { conversationId: message.conversationId }
  });
  return {
    readBy: readers.map((r) => ({
      userId: r.user.id,
      username: r.user.fullName || "Unknown",
      avatarUrl: r.user.avatarUrl
    })),
    totalReads: readers.length,
    totalMembers
  };
};
