var handler74 = async (input, ctx) => {
  const { userId } = ctx.auth;
  if (!userId) {
    throw AppError.unauthorized("User not authenticated");
  }
  const { conversationId } = input;
  const conversation = await ctx.db.chatConversation.findFirst({
    where: {
      id: conversationId,
      members: {
        some: { userId }
      }
    },
    include: {
      members: {
        include: {
          user: {
            select: {
              id: true,
              fullName: true,
              email: true,
              avatarUrl: true
            }
          }
        }
      }
    }
  });
  if (!conversation) {
    throw AppError.notFound("Conversation not found or access denied");
  }
  const userMember = conversation.members.find((m) => m.userId === userId);
  const unreadCount = await ctx.db.chatMessage.count({
    where: {
      conversationId,
      sequence: { gt: userMember?.lastReadSeq || 0 },
      deletedAt: null
    }
  });
  const lastMessage = await ctx.db.chatMessage.findFirst({
    where: {
      conversationId,
      deletedAt: null
    },
    orderBy: {
      createdAt: "desc"
    },
    select: {
      id: true,
      content: true,
      authorUserId: true,
      createdAt: true
    }
  });
  return {
    id: conversation.id,
    type: conversation.type,
    name: conversation.name,
    topic: conversation.topic,
    isPublic: conversation.type === "CHANNEL",
    workspaceId: conversation.workspaceId,
    projectId: conversation.projectId,
    parentMessageId: conversation.parentMessageId,
    createdBy: null,
    isArchived: conversation.isArchived,
    memberCount: conversation.members.length,
    unreadCount,
    members: conversation.members.map((m) => ({
      userId: m.userId,
      role: m.role,
      isMuted: m.isMuted,
      joinedAt: m.joinedAt,
      user: {
        ...m.user,
        fullName: m.user.fullName || "Unknown"
      }
    })),
    lastMessage: lastMessage || null,
    createdAt: conversation.createdAt,
    updatedAt: conversation.updatedAt,
    deletedAt: conversation.deletedAt
  };
};
