// src/services/clerk/webhook.ts
init_env();
init_logger();
var import_svix = __toESM(require_dist8(), 1);
var ClerkWebhookService = {
  verifyWebhook(payload, headers) {
    const SIGNING_SECRET = env2.CLERK_WEBHOOK_SIGNING_SECRET;
    if (!SIGNING_SECRET) {
      throw new Error("CLERK_WEBHOOK_SIGNING_SECRET is missing");
    }
    const wh = new import_svix.Webhook(SIGNING_SECRET);
    try {
      const verified = wh.verify(payload, {
        "svix-id": headers["svix-id"],
        "svix-timestamp": headers["svix-timestamp"],
        "svix-signature": headers["svix-signature"]
      });
      return Promise.resolve(verified);
    } catch (err) {
      logger.error({ err }, "Webhook verification failed");
      throw new Error("Verification Failed");
    }
  }
};

// src/app/routes/webhooks.ts
init_logger();
init_db();
init_redis();
var webhookRouter = new Hono2;
webhookRouter.post("/api/webhooks/clerk", async (c) => {
  const payload = await c.req.text();
  const headers = {
    "svix-id": c.req.header("svix-id"),
    "svix-timestamp": c.req.header("svix-timestamp"),
    "svix-signature": c.req.header("svix-signature")
  };
  try {
    const evt = await ClerkWebhookService.verifyWebhook(payload, headers);
    const eventType = evt.type;
    logger.info({ eventType }, "Processing Clerk Webhook");
    switch (eventType) {
      case "user.created":
      case "user.updated": {
        const { id, email_addresses, first_name, last_name, image_url } = evt.data;
        const primaryEmail = email_addresses.find((e) => e.id === evt.data.primary_email_address_id) || email_addresses[0];
        if (!primaryEmail?.email_address) {
          logger.warn({ userId: id }, "Skipping user sync: No email found");
          return c.json({ success: true, skipped: "no_email" });
        }
        await syncUser({
          clerkId: id,
          email: primaryEmail.email_address,
          fullName: `${first_name || ""} ${last_name || ""}`.trim(),
          avatarUrl: image_url,
          emailVerified: primaryEmail.verification?.status === "verified"
        }, { db, redis });
        logger.info({ userId: id }, "Successfully synced user");
        break;
      }
      case "user.deleted":
        logger.info({ userId: evt.data.id }, "User deleted event ignored (Soft Delete Policy)");
        break;
      default:
        logger.info({ eventType }, "Ignored unhandled event type");
    }
    return c.json({ success: true });
  } catch (err) {
    logger.error({ err }, "Webhook Error");
    return c.text("Bad Request", 400);
  }
});
var webhooks_default = webhookRouter;

